const focalToFOV = (focalLength, sensorHeight, sensorWidth) => {
    const fovH = 2 * Math.atan(sensorHeight / (2 * focalLength));
    const fovW = 2 * Math.atan(sensorWidth / (2 * focalLength));
    const degFovH = fovH * (180 / Math.PI); // Convert radians to degrees
    const degFovW = fovW * (180 / Math.PI); // Convert radians to degrees
    return [degFovH, degFovW];
};

const fovRectSize = (fov, imageFov = 2) => {
    const fovH = fov[0];
    const fovW = fov[1];

    const tan = (theta) => Math.tan((theta * Math.PI) / 180);

    return [
        (tan(fovH / 2) / tan(imageFov / 2)),
        (tan(fovW / 2) / tan(imageFov / 2))
    ]
}

document.addEventListener("DOMContentLoaded", function() {
    const messierObjectSelect = document.getElementById("messier_object");
    Object.entries(messierNames).forEach(([key, value]) => {
        const option = document.createElement("option");
        option.value = key;
        option.textContent = value == null ? key : `${key} - ${JSON.parse('"' + value + '"')}`;
        messierObjectSelect.appendChild(option);
    });
});


document.getElementById("camera_name_searchbox").addEventListener("input", function() {
    const searchValue = this.value.toLowerCase();
    const cameraSuggestions = document.getElementById("camera_name_suggestions");
    const cameraOptions = Object.keys(cameras).filter(cameraName => cameraName.toLowerCase().includes(searchValue)).splice(0, 5); // Limit to 5 suggestions
    cameraSuggestions.innerHTML = "";
    if (searchValue.trim() === "" || cameraOptions.length === 0) {
        cameraSuggestions.style.display = "none";
        return;
    }
    cameraOptions.forEach(cameraName => {
        const option = document.createElement("li");
        option.textContent = cameraName;
        option.classList.add("camera-suggestion");
        option.addEventListener("click", function() {
            document.getElementById("camera_name_searchbox").value = cameraName;
            cameraSuggestions.innerHTML = "";
            cameraSuggestions.style.display = "none";

            document.getElementById("sensor_width").value = cameras[cameraName].w;
            document.getElementById("sensor_height").value = cameras[cameraName].h;
        });
        cameraSuggestions.appendChild(option);
    });
    cameraSuggestions.style.display = "block";
});

// Hide suggestions when clicking outside the searchbox
document.addEventListener('click', function(e) {
    const searchbox = document.getElementById('searchbox');
    const suggestions = document.getElementById('camera_name_suggestions');
    if (!searchbox.contains(e.target)) {
        suggestions.style.display = 'none';
    }
});

function createFOVPreview() {

    const messierObject = document.getElementById("messier_object").value;
    const focalLength = parseFloat(document.getElementById("focal_length").value);
    const sensorWidth = parseFloat(document.getElementById("sensor_width").value);
    const sensorHeight = parseFloat(document.getElementById("sensor_height").value);

    if (isNaN(focalLength) || isNaN(sensorWidth) || isNaN(sensorHeight)) {
        alert("Please enter valid numbers for focal length, sensor width, and sensor height.");
        return;
    }

    if (!messierObject) {
        alert("Please select a Messier object.");
        return;
    }

    const fov = focalToFOV(focalLength, sensorHeight, sensorWidth);

    

    const rectSize = fovRectSize(fov); //percent of the screen to cover
    

    const canvas = document.createElement("canvas");
    canvas.width = 800;
    canvas.height = 800;
    const ctx = canvas.getContext("2d");

    // Draw the Messier object image
    const messierImage = new Image();
    messierImage.src = `/assets/messier/${messierObject.toLowerCase()}_2deg.webp`;
    messierImage.onload = function() {
        ctx.drawImage(messierImage, 0, 0, canvas.width, canvas.height);
        for (let i = 0; i < canvas.width * canvas.height; i++) {
            const x = i % canvas.width;
            const y = Math.floor(i / canvas.width);
            const pixel = ctx.getImageData(x, y, 1, 1).data;
            if (pixel[0] === 0 && pixel[1] === 0 && pixel[2] === 0) {
                // To save space, the we store the image as pure black and white, so to make it look the same, we replace the black pixels with their original blue color
                ctx.fillStyle = "#010120";
                ctx.fillRect(x, y, 1, 1);
            }
        }

        ctx.strokeStyle = "red";
        ctx.lineWidth = 2;
        ctx.strokeRect(
            canvas.width * (1 - rectSize[1]) / 2, // Center the rectangle horizontally
            canvas.height * (1 - rectSize[0]) / 2, // Center the rectangle vertically
            canvas.width * rectSize[1], // Width of the rectangle
            canvas.height * rectSize[0]  // Height of the rectangle
        );

        ctx.font = "24px Arial";
        ctx.strokeText(`FOV: ${fov[0].toFixed(2)}° x ${fov[1].toFixed(2)}°`, 10, 20);

        if (fov[0] > 2 || fov[1] > 2) {
            ctx.strokeText("Warning: FOV exceeds 2 degrees!", 10, 45);
            ctx.strokeText("Camera will capture more than the previewed area.", 10, 70);
        }

        

        const base64Image = canvas.toDataURL("image/png");
        document.getElementById("fov_preview_image").src = base64Image;
        document.getElementById("fov_preview_image").style.display = "block";
    }
}

document.getElementById("calculate-button").addEventListener("click", createFOVPreview);
